'use strict';

// 视频参数计划（通用）：DashScope video-synthesis 全模型约束表 + 素材校验 + 请求组装。
// 覆盖：wan3.0-video/-prime、HappyHorse 1.0/1.1（i2v/r2v）、Wan2.7（i2v/r2v）。
// 素材 media 统一为官方结构 [{ type, url }]：图片支持 dataURI（mime;base64），
// 音视频必须经 createAssetUrl 登记为公网 URL（防 URL/路径绕过）。禁止素材自带 url/path/正文。
// 说明：duration 永远显式写入；音频输出/扩展等参数仅对支持的模型写入。

const { MODELS, modelTypeOf } = require('@aigc-desk/contracts');
const { KINDS, OFFICIAL, LIMITS } = require('./kinds.cjs');

// —— 默认宽高比集合（按各模型官方 API 参考，避免误造非法值）——
const RATIOS_WAN3 = Object.freeze(['adaptive', '16:9', '4:3', '1:1', '3:4', '9:16']); // 万相3.0：adaptive 默认
const RATIOS_WAN27_R2V = Object.freeze(['16:9', '9:16', '1:1', '4:3', '3:4']); // 万相2.7-参考生视频：16:9 默认
const RATIOS_HH_R2V = Object.freeze(['16:9', '9:16', '3:4', '4:3', '4:5', '5:4', '1:1', '9:21', '21:9']); // HappyHorse-参考生视频：16:9 默认
const RESOLUTIONS_WAN3 = Object.freeze(['480P', '720P', '1080P']);
const RESOLUTIONS_NEW = Object.freeze(['720P', '1080P']);
const RESOLUTIONS_FULL = Object.freeze(['480P', '720P', '1080P']);

// media 规则：每种 kind 的官方 type / 最大数量 / 是否支持 dataURI。
const MEDIA_NONE = Object.freeze({});
const MEDIA_WAN3 = Object.freeze({
  [KINDS.IMAGE]: Object.freeze({ type: 'reference_image', max: 10, dataUri: true }),
  [KINDS.VIDEO]: Object.freeze({ type: 'reference_video', max: 5, dataUri: false }),
  [KINDS.AUDIO]: Object.freeze({ type: 'reference_audio', max: 5, dataUri: false })
});
const MEDIA_FIRST_FRAME = Object.freeze({
  [KINDS.IMAGE]: Object.freeze({ type: 'first_frame', max: 1, dataUri: true })
});
const MEDIA_HH_R2V = Object.freeze({
  [KINDS.IMAGE]: Object.freeze({ type: 'reference_image', max: 9, dataUri: true })
});
const MEDIA_WAN27_R2V = Object.freeze({
  [KINDS.IMAGE]: Object.freeze({ type: 'reference_image', max: 5, dataUri: true }),
  [KINDS.VIDEO]: Object.freeze({ type: 'reference_video', max: 5, dataUri: false }),
  [KINDS.AUDIO]: Object.freeze({ type: 'reference_audio', max: 1, dataUri: false })
});

// 模型规则表：resolutions / ratios / duration 区间 / 是否允许 -1 / 支持的 parameters / media 规则。
function videoRule(model) {
  switch (model) {
    case MODELS.WAN3_VIDEO:
    case MODELS.WAN3_VIDEO_PRIME:
      return {
        model,
        kind: 'wan3',
        resolutions: RESOLUTIONS_WAN3,
        ratios: RATIOS_WAN3,
        fixedAspect: false,
        defaultRatio: 'adaptive', // 官方默认：自适应
        durationMin: 2,
        durationMax: 30,
        allowAuto: true, // -1 允许（智能时长）
        parameters: ['resolution', 'ratio', 'duration', 'audio', 'prompt_extend', 'watermark'],
        media: MEDIA_WAN3
      };
    case MODELS.HH_1_0_I2V:
    case MODELS.HH_1_1_I2V:
      return {
        model,
        kind: 'i2v',
        resolutions: RESOLUTIONS_FULL, // 官方：480P/720P/1080P（默认1080P）
        ratios: [], // 官方图生视频(基于首帧)无 ratio 参数，输出画幅随首帧
        fixedAspect: true,
        defaultRatio: null,
        durationMin: 3,
        durationMax: 15,
        allowAuto: false,
        parameters: ['resolution', 'duration', 'watermark'],
        media: MEDIA_FIRST_FRAME,
        requireFirstFrame: true
      };
    case MODELS.HH_1_1_R2V:
      return {
        model,
        kind: 'r2v',
        resolutions: RESOLUTIONS_FULL, // 官方：480P/720P/1080P（默认1080P）
        ratios: RATIOS_HH_R2V, // 官方：16:9 默认/9:16/3:4/4:3/4:5/5:4/1:1/9:21/21:9
        fixedAspect: false,
        defaultRatio: '16:9',
        durationMin: 3,
        durationMax: 15,
        allowAuto: false,
        parameters: ['resolution', 'ratio', 'duration', 'watermark'],
        media: MEDIA_HH_R2V
      };
    case MODELS.WAN27_I2V:
      return {
        model,
        kind: 'i2v',
        resolutions: RESOLUTIONS_NEW, // 官方：720P/1080P（默认1080P）
        ratios: [], // 官方图生视频2.7 无 ratio 参数，输出画幅随输入素材
        fixedAspect: true,
        defaultRatio: null,
        durationMin: 2,
        durationMax: 15,
        allowAuto: false,
        parameters: ['resolution', 'duration', 'watermark'],
        media: MEDIA_FIRST_FRAME,
        requireFirstFrame: true
      };
    case MODELS.WAN27_R2V:
      return {
        model,
        kind: 'r2v',
        resolutions: RESOLUTIONS_NEW, // 官方：720P/1080P（默认1080P）
        ratios: RATIOS_WAN27_R2V, // 官方：16:9 默认/9:16/1:1/4:3/3:4
        fixedAspect: false,
        defaultRatio: '16:9',
        durationMin: 2,
        durationMax: 15, // 仅图片/音频参考时 2~15；含参考视频时 ≤10（validateWan3Assets 内动态收紧）
        allowAuto: false,
        parameters: ['resolution', 'ratio', 'duration', 'watermark'],
        media: MEDIA_WAN27_R2V
      };
    default:
      return null;
  }
}

function getVideoModelRule(model) {
  const rule = videoRule(model);
  if (!rule) {
    const err = new Error(`不支持的视频模型：${model}`);
    err.code = 'WAN3_MODEL_INVALID';
    err.status = 400;
    throw err;
  }
  return rule;
}

function isVideoModel(model) {
  return typeof model === 'string' && modelTypeOf(model) === 'video';
}

// 导出 UI 下拉候选用的精简目录（不含素材对象）。
function listVideoModelRules() {
  const out = [];
  for (const m of [MODELS.WAN3_VIDEO, MODELS.WAN3_VIDEO_PRIME, MODELS.HH_1_0_I2V,
    MODELS.HH_1_1_I2V, MODELS.HH_1_1_R2V, MODELS.WAN27_I2V, MODELS.WAN27_R2V]) {
    const rule = videoRule(m);
    out.push({
      model: rule.model,
      kind: rule.kind,
      resolutions: rule.resolutions.slice(),
      ratios: rule.ratios.slice(),
      fixedAspect: !!rule.fixedAspect,
      defaultRatio: rule.defaultRatio || null,
      durationMin: rule.durationMin,
      durationMax: rule.durationMax,
      allowAuto: rule.allowAuto,
      mediaImageMax: rule.media[KINDS.IMAGE] ? rule.media[KINDS.IMAGE].max : 0,
      mediaVideoMax: rule.media[KINDS.VIDEO] ? rule.media[KINDS.VIDEO].max : 0,
      mediaAudioMax: rule.media[KINDS.AUDIO] ? rule.media[KINDS.AUDIO].max : 0
    });
  }
  return out;
}

// 兼容旧引用：默认按 wan3.0 规则（桌面版行为不变）。
const WAN3_DEFAULT_RULE = videoRule(MODELS.WAN3_VIDEO);
const RESOLUTIONS = WAN3_DEFAULT_RULE.resolutions;
const RATIOS = WAN3_DEFAULT_RULE.ratios;
const WAN3_MODELS = Object.freeze([MODELS.WAN3_VIDEO, MODELS.WAN3_VIDEO_PRIME]);
const MEDIA_TYPE_BY_KIND = Object.freeze({
  [KINDS.IMAGE]: 'reference_image',
  [KINDS.VIDEO]: 'reference_video',
  [KINDS.AUDIO]: 'reference_audio',
  [KINDS.TEXT]: 'file',
  [KINDS.DOCUMENT]: 'file'
});

// 禁止素材对象携带客户端 URL/路径/正文，防绕过已登记素材。
const FORBIDDEN_ASSET_FIELDS = Object.freeze([
  'url', 'uri', 'path', 'filePath', 'signedUrl', 'signedURL', 'content', 'textContent', 'base64'
]);

function adapterError(code, message, status = 400) {
  const error = new Error(`${code}: ${message}`);
  error.code = code;
  error.status = status;
  return error;
}

function pickRule(model) {
  return model && videoRule(model) ? videoRule(model) : WAN3_DEFAULT_RULE;
}

// duration/resolution/ratio 归一化：只保留该模型支持的参数；duration 必须显式。
// 官方口径：i2v 系列无 ratio（画幅随首帧），ratio 即使传入也忽略；r2v/文生 允许 set 内取值。
function normalizeWan3Parameters(raw = {}, model) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw adapterError('WAN3_PARAMETER_INVALID', '视频参数必须是对象');
  }
  const rule = pickRule(model);
  const { resolution, ratio, duration } = raw;
  if (!rule.resolutions.includes(resolution)) {
    throw adapterError('WAN3_PARAMETER_INVALID', `resolution 仅支持 ${rule.resolutions.join('、')}`);
  }
  if (duration === undefined || duration === null || duration === '') {
    throw adapterError('WAN3_DURATION_REQUIRED', 'duration 必须显式提供');
  }
  const okAuto = rule.allowAuto && duration === -1;
  if (!okAuto && !(Number.isSafeInteger(duration) && duration >= rule.durationMin && duration <= rule.durationMax)) {
    throw adapterError('WAN3_PARAMETER_INVALID', `duration 必须是 ${rule.durationMin}..${rule.durationMax} 的整数${rule.allowAuto ? ' 或 -1' : ''}`);
  }

  const out = { resolution, duration };
  if (rule.fixedAspect) {
    // i2v 官方无 ratio：忽略客户端传入的 ratio，不写入请求
  } else {
    const ratioValue = (ratio === undefined || ratio === null || ratio === '') ? rule.defaultRatio : ratio;
    if (!rule.ratios.includes(ratioValue)) {
      throw adapterError('WAN3_PARAMETER_INVALID', `ratio 仅支持 ${rule.ratios.join('、')}`);
    }
    out.ratio = ratioValue;
  }
  // wan3 系默认与桌面版旧行为一致：audio/prompt_extend 开启、去水印。
  if (rule.parameters.includes('audio')) out.audio = raw.audio !== false;
  if (rule.parameters.includes('prompt_extend')) out.prompt_extend = raw.prompt_extend !== false;
  if (rule.parameters.includes('watermark')) out.watermark = typeof raw.watermark === 'boolean' ? raw.watermark : false;
  return out;
}

function validateAsset(asset) {
  if (!asset || typeof asset !== 'object' || Array.isArray(asset)) {
    throw adapterError('WAN3_ASSET_INVALID', '素材对象无效');
  }
  if (FORBIDDEN_ASSET_FIELDS.some(field => Object.hasOwn(asset, field))) {
    throw adapterError('WAN3_ASSET_INVALID', '素材对象不能携带客户端 URL、路径或正文');
  }
  if (typeof asset.id !== 'string' || !asset.id
    || !Object.hasOwn(MEDIA_TYPE_BY_KIND, asset.kind)
    || !['ready'].includes(asset.status)
    || typeof asset.mimeType !== 'string' || !asset.mimeType
    || !Number.isSafeInteger(asset.byteSize) || asset.byteSize < 0
    || typeof asset.sha256 !== 'string' || !/^[a-f0-9]{64}$/i.test(asset.sha256)) {
    throw adapterError('WAN3_ASSET_INVALID', '素材未经过规范化或状态不可用');
  }
  if (asset.kind === KINDS.IMAGE && !/^image\/(?:png|jpeg|webp|bmp|x-ms-bmp)$/i.test(asset.mimeType)) {
    throw adapterError('WAN3_ASSET_INVALID', '图片素材格式无效');
  }
  if (asset.kind === KINDS.VIDEO && !/^video\/(?:mp4|quicktime)$/i.test(asset.mimeType)) {
    throw adapterError('WAN3_ASSET_INVALID', '视频素材格式无效');
  }
  if (asset.kind === KINDS.AUDIO && !/^audio\/(?:mpeg|wav|x-wav)$/i.test(asset.mimeType)) {
    throw adapterError('WAN3_ASSET_INVALID', '音频素材格式无效');
  }
  if ([KINDS.VIDEO, KINDS.AUDIO].includes(asset.kind)
    && (!Number.isFinite(asset.durationSeconds) || asset.durationSeconds < 1 || asset.durationSeconds > 15)) {
    throw adapterError('WAN3_REFERENCE_DURATION_EXCEEDED', '单条音视频素材时长必须为 1..15 秒');
  }
  return asset;
}

// 校验素材清单；model 决定每类素材的数量/类型上限。
function validateWan3Assets(assets = [], { outputDuration = null, model } = {}) {
  if (!Array.isArray(assets)) throw adapterError('WAN3_ASSET_INVALID', '素材清单必须是数组');
  const rule = pickRule(model);
  const ids = new Set();
  const counts = { [KINDS.IMAGE]: 0, [KINDS.VIDEO]: 0, [KINDS.AUDIO]: 0, [KINDS.TEXT]: 0, [KINDS.DOCUMENT]: 0 };
  let videoSeconds = 0;
  let audioSeconds = 0;
  let total = 0;

  for (const asset of assets) {
    validateAsset(asset);
    if (ids.has(asset.id)) throw adapterError('WAN3_ASSET_INVALID', '素材清单含重复 ID');
    ids.add(asset.id);
    counts[asset.kind] += 1;
    total += 1;
    if (asset.kind === KINDS.VIDEO) videoSeconds += Number(asset.durationSeconds);
    if (asset.kind === KINDS.AUDIO) audioSeconds += Number(asset.durationSeconds);
  }

  const limits = { [KINDS.IMAGE]: LIMITS[KINDS.IMAGE], [KINDS.VIDEO]: LIMITS[KINDS.VIDEO], [KINDS.AUDIO]: LIMITS[KINDS.AUDIO] };
  for (const k of [KINDS.IMAGE, KINDS.VIDEO, KINDS.AUDIO]) {
    const media = rule.media[k];
    const hard = media ? media.max : 0;
    const generic = media && k === KINDS.IMAGE ? limits[k] : limits[k];
    if (counts[k] > Math.min(hard === undefined ? Infinity : hard, generic)) {
      throw adapterError('WAN3_REFERENCE_LIMIT_EXCEEDED', `素材类型 ${k} 数量超过 ${model || '默认'} 模型上限`);
    }
  }
  if (counts[KINDS.TEXT] + counts[KINDS.DOCUMENT] > 1) {
    throw adapterError('WAN3_FILE_LIMIT_EXCEEDED', '文本与文档合计最多一个 file');
  }
  if (total > LIMITS.total) throw adapterError('WAN3_REFERENCE_LIMIT_EXCEEDED', '素材总数超过上限');
  if (videoSeconds > 15 || audioSeconds > 15) {
    throw adapterError('WAN3_REFERENCE_DURATION_EXCEEDED', '视频和音频各自合计最多 15 秒');
  }
  if (rule.requireFirstFrame && counts[KINDS.IMAGE] !== 1) {
    throw adapterError('WAN3_FIRST_FRAME_REQUIRED', '该模型必须有且仅有 1 张首帧图片');
  }
  // 有参考视频时：参考视频总时长 + 输出时长 ≤ 30 秒。
  if (counts[KINDS.VIDEO] > 0 && outputDuration !== null && outputDuration !== undefined) {
    if (outputDuration === -1) {
      throw adapterError('WAN3_PARAMETER_INVALID', '有输入视频时必须指定确定的输出时长');
    }
    if (!Number.isSafeInteger(outputDuration) || videoSeconds + outputDuration > 30) {
      throw adapterError('WAN3_TOTAL_DURATION_EXCEEDED', '输入视频总时长加输出时长不能超过 30 秒');
    }
    // 官方：wan2.7-r2v 含参考视频时输出时长上限 10 秒（仅图片/音频参考时才可 2~15）
    if (model === MODELS.WAN27_R2V && Number.isSafeInteger(outputDuration) && outputDuration > 10) {
      throw adapterError('WAN3_PARAMETER_INVALID', 'wan2.7-r2v 含参考视频时 duration 必须为 2..10 的整数');
    }
  }
  return { total, counts, videoSeconds, audioSeconds };
}

function toMediaUrl(asset, dataUri) {
  // 服务器版：已校验的公网图片 URL 交由 createAssetUrl 透传。
  if (dataUri && !asset.imageData && asset.publicUrl) return null;
  if (dataUri) {
    if (typeof asset.imageData !== 'string' || !asset.imageData) {
      throw adapterError('WAN3_ASSET_INVALID', '图片素材缺少数据');
    }
    const mime = (asset.mimeType || 'application/octet-stream').toLowerCase();
    return `data:${mime};base64,${asset.imageData}`;
  }
  return null; // 需要 createAssetUrl
}

// 组装官方请求体：{ model, input:{prompt, media:[{type,url}]}, parameters }。
function buildWan3Request({ model, compiledPrompt, parameters, media = [], createAssetUrl = null } = {}) {
  const rule = getVideoModelRule(model);
  if (typeof compiledPrompt !== 'string' || !compiledPrompt.trim()) {
    throw adapterError('WAN3_PROMPT_INVALID', '提示词不能为空');
  }
  const normalizedParameters = normalizeWan3Parameters(parameters, model);
  validateWan3Assets(media, { outputDuration: normalizedParameters.duration, model });

  const materializedMedia = media.map(item => {
    const mediaRule = rule.media[item.kind];
    if (!mediaRule) throw adapterError('WAN3_ASSET_INVALID', `模型 ${model} 不支持 ${item.kind} 素材`);
    const url = toMediaUrl(item, mediaRule.dataUri);
    if (!url) {
      if (typeof createAssetUrl !== 'function') {
        throw adapterError('WAN3_MEDIA_URL_INVALID', '媒体签名函数未配置', 503);
      }
      // createAssetUrl 仅允许返回登记过的公网 URL（内部实现负责白名单/签名）。
      const signed = createAssetUrl(item);
      if (typeof signed !== 'string' || !/^https?:\/\//i.test(signed)) {
        throw adapterError('WAN3_MEDIA_URL_INVALID', '媒体签名返回非法 URL');
      }
      return { type: mediaRule.type, url: signed };
    }
    return { type: mediaRule.type, url };
  });

  return {
    model,
    input: { prompt: compiledPrompt, ...(materializedMedia.length ? { media: materializedMedia } : {}) },
    parameters: normalizedParameters
  };
}

module.exports = {
  WAN3_MODELS,
  RESOLUTIONS,
  RATIOS,
  MEDIA_TYPE_BY_KIND,
  FORBIDDEN_ASSET_FIELDS,
  listVideoModelRules,
  getVideoModelRule,
  isVideoModel,
  normalizeWan3Parameters,
  validateAsset,
  validateWan3Assets,
  buildWan3Request
};
